// === Tab: mySketch ===
let bubbles = [];
nbubbles = 150;
attractStrength = -0.3;


function setup() {
	createCanvas(600, 450);
	for (i = 0; i < nbubbles; i++) {
		bubbles.push(new bubble(random(0, width), random(0, height), random(10, 30), 0));
	}
	ellipseMode(RADIUS);
}

function draw() {
	background(0);
	noFill();

	if (((window.isBeat || false) || (typeof window.is_silent !== 'undefined' ? !window.is_silent : mouseIsPressed))) {
		i = int(random(bubbles.length));
		bubbles[i].pos.set(float((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX)))), float((window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY)))));
	}

	for (i = 0; i < nbubbles; i++) {
		b = bubbles[i];

		if (dist((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))), b.pos.x, b.pos.y) < b.r) {
			b.m = min(b.m + 0.01, 1.0);
		} else {
			b.m = max(b.m - 0.001, 0.0);
		}

		b.resetForce();
		b.inForce(gravity(b));

		for (j = 0; j < nbubbles; j++) {
			if (i != j) {
				b.inForce(bubbles[j].outForce(b));
			}
		}
		b.updatePos(0.5);

		for (j = 0; j < nbubbles; j++) {
			if (i != j) {
				b.inForce(bubbles[j].outForce(b));
			}
		}
		b.updatePos(0.8);

		for (j = 0; j < nbubbles; j++) {
			if (i != j) {
				b.inForce(bubbles[j].outForce(b));
			}
		}
		b.updatePos(0.2);

		b.display();
	}
}

function gravity(b) {
	return createVector(0, 30 * b.m + 1);
}

class bubble {
	constructor(x_, y_, r_, m_) {
		this.pos = createVector(x_, y_);
		this.r = r_;
		this.m = m_;
		this.force = createVector(0, 0);
		this.cs = color(random(255), random(255), random(255));
		this.cf = color(random(255), random(255), random(255));
	}

	resetForce() {
		this.force.set(0, 0);
	}

	inForce(f) {
		this.force.add(f);
	}

	updatePos(a) {
		this.pos.add(this.force.mult(a));
		if (this.pos.y + this.r > height) {
			this.pos.y = height - this.r;
		}
		this.pos.x = constrain(this.pos.x, 0, width);
	}

	display() {
		stroke(this.cs);
		noFill();
		ellipse(this.pos.x, this.pos.y, this.r - 1.5, this.r - 1.5);
		fill(this.cf);
		if (this.m == 1) {
			ellipse(this.pos.x, this.pos.y, this.r - 1.5, this.r - 1.5);
		} else if (this.m > 0) {
			arc(this.pos.x, this.pos.y, this.r - 1.5, this.r - 1.5, HALF_PI - PI * this.m, HALF_PI + PI * this.m, OPEN);
		}
	}

	outForce(b) {
		this.f = b.pos.copy();
		this.f.sub(this.pos);
		this.d = this.f.mag();
		if (this.d > b.r + this.r) {
			return this.f.mult(attractStrength * (this.d - b.r - this.r) / this.d / this.d / this.d);
		} else {
			return this.f.mult(-(this.d - b.r - this.r) / this.d);
		}
	}

}

